`timescale 1ns/1ps
// Qualified v3 architecture: 8->16->16->8->1, kernels 3/3/3/1.
// Input features Q7.16; internal activations Q5.10 (16 bits).
// Weights signed Q3.14 (18 bits). Internal format is parameterized.
// 16 parallel channel MACs, banked activation RAM. No ARM computations.
// Features MUST be generated by the matching PL feature extractor.

module cnn_v3_fixed #(
    parameter integer FREQ = 64,
    TIME = 20,
    DATA_BITS = 16,
    DATA_FRAC = 10,
    parameter COEFF_DIR = "pl/coeff"
)
(
    input  wire clk,
    input  wire rst_n,
    input  wire feature_valid,
    output wire feature_ready,
    input  wire [12:0] feature_address,
    input  wire [2:0] feature_channel,
    input  wire signed [23:0] feature_data,
    input  wire start,
    output wire busy,
    output reg done,
    output reg load_error,
    input  wire [8:0] feature_frequency_count,
    output reg mask_valid,
    input  wire mask_ready,
    output reg [12:0] mask_address,
    output reg [15:0] mask_data
);

    localparam integer DEPTH = FREQ * TIME;
    localparam IDLE = 0, INIT = 1, ISSUE = 2, DRAIN = 3, OUT_READ = 4, OUT_HOLD = 5, WRITE = 6;
    reg [2:0] state;
    reg [1:0] layer;
    reg [8:0] run_frequency_count;
    reg [8:0] f;
    reg [$clog2(TIME + 1) - 1:0] t;
    reg [4:0] o;
    reg [1:0] kx, ky;
    reg [3:0] issued;
    reg [1:0] kernel;
    reg [4:0] cin, cout;
    reg [8:0] weight_base;
    reg [5:0] bias_base;
    reg signed [10:0] source_f;
    reg signed [$clog2(TIME + 1) + 1:0] source_t;
    reg signed [12:0] source_address;
    reg [8:0] weight_address;
    reg source_valid;
    reg [$clog2(FREQ * TIME * 8 + 2)-1:0] loaded;
    reg signed [47:0] accumulator, finished_acc;
    reg signed [23:0] biases[0:40];
    reg [15:0] sigmoid[0:1024];
    (* ram_style="block" *) reg [15:0] mask_ram[0:DEPTH - 1];
    wire signed [DATA_BITS - 1:0] activations[0:15];
    wire signed [17:0] weights[0:15];
    reg signed [DATA_BITS + 17:0] products[0:15];
    reg rd_valid, rd_last, prod_valid, prod_last, sum_valid, sum_last;
    reg quarter_valid, quarter_last, half_valid, half_last;
    reg signed [47:0] sum_quarter[0:3];
    (* use_dsp="yes" *) reg signed [47:0] sum_half[0:1];
    (* use_dsp="yes" *) reg signed [47:0] sum_reg;
    (* use_dsp="yes" *) wire signed [47:0] sum_l1[0:7], sum_l2[0:3], sum_l3[0:1];
    (* use_dsp="yes" *) wire signed [47:0] sum_comb = sum_l3[0] + sum_l3[1];
    (* use_dsp="yes" *) wire signed [47:0] half_add_0 = sum_quarter[0] + sum_quarter[1];
    (* use_dsp="yes" *) wire signed [47:0] half_add_1 = sum_quarter[2] + sum_quarter[3];
    (* use_dsp="yes" *) wire signed [47:0] final_sum_add = sum_half[0] + sum_half[1];
    (* use_dsp="yes" *) wire signed [47:0] final_acc = accumulator + sum_reg;
    wire signed [47:0] scaled = finished_acc >>> 14;
    reg signed [DATA_BITS - 1:0] write_value;
    integer sigmoid_index;
    reg [15:0] write_mask;
    wire write_enable = (state == WRITE);
    wire [12:0] write_address = f * TIME + t;
    wire input_a = (layer == 0 || layer == 2);
    assign feature_ready = (state == IDLE);
    assign busy = (state != IDLE);
    initial
    begin
        $readmemh({COEFF_DIR, "/bias.mem"}, biases);
        $readmemh({COEFF_DIR, "/sigmoid.mem"}, sigmoid);
    end

    always @*
    begin
        case
            (layer)
            0:
            begin
                kernel = 3;
                cin = 8;
                cout = 16;
                weight_base = 0;
                bias_base = 0;
            end
            1:
            begin
                kernel = 3;
                cin = 16;
                cout = 16;
                weight_base = 144;
                bias_base = 16;
            end
            2:
            begin
                kernel = 3;
                cin = 16;
                cout = 8;
                weight_base = 288;
                bias_base = 32;
            end
            default:
            begin
                kernel = 1;
                cin = 8;
                cout = 1;
                weight_base = 360;
                bias_base = 40;
            end
        endcase
        source_f = f + ky - kernel / 2;
        source_t = t + kx - kernel / 2;
        source_valid = (source_f >= 0 && source_f < run_frequency_count && source_t >= 0 && source_t < TIME);
        source_address = source_f * TIME + source_t;
        weight_address = weight_base + o * kernel * kernel + kx * kernel + ky;
        if (scaled > ((64'sd1 << (DATA_BITS - 1)) - 1)) write_value = (64'sd1 << (DATA_BITS - 1)) - 1;
        else if (scaled < -(64'sd1 << (DATA_BITS - 1))) write_value = -(64'sd1 << (DATA_BITS - 1));
        else write_value = scaled[DATA_BITS - 1:0];
        if (layer != 3 && write_value < 0) write_value = 0;
        sigmoid_index = ($signed(write_value) + (8 << DATA_FRAC) + (1 << (DATA_FRAC - 7))) >>> (DATA_FRAC - 6);
        if ($signed(write_value) <= - (8 << DATA_FRAC)) write_mask = 0;
        else if ($signed(write_value) >= (8 << DATA_FRAC)) write_mask = 65535;
        else write_mask = sigmoid[sigmoid_index];
    end
    genvar ad;
    generate
        for (ad = 0;ad < 8;ad = ad + 1)
        begin
            :adder1
            assign sum_l1[ad] = $signed(products[2 * ad]) + $signed(products[2 * ad + 1]);
        end
        for (ad = 0;ad < 4;ad = ad + 1)
        begin
            :adder2
            assign sum_l2[ad] = sum_l1[2 * ad] + sum_l1[2 * ad + 1];
        end
        for (ad = 0;ad < 2;ad = ad + 1)
        begin
            :adder3
            assign sum_l3[ad] = sum_l2[2 * ad] + sum_l2[2 * ad + 1];
        end
    endgenerate
    genvar c;
    generate
        for (c = 0;c < 16;c = c + 1)
        begin
            :bank
            (* rom_style="distributed" *) reg signed [17:0] rom[0:360];
            wire signed [DATA_BITS - 1:0] activation_a, activation_b;
            reg padding_valid;
            reg signed [17:0] weight;
            localparam DIGIT0 = 8'd48 + (c / 10), DIGIT1 = 8'd48 + (c % 10);
            initial $readmemh({COEFF_DIR, "/weight_lane_", DIGIT0[7:0], DIGIT1[7:0], ".mem"}, rom);
            assign activations[c] = (c < cin && padding_valid)?(input_a?activation_a:activation_b):0;
            assign weights[c] = weight;
            wire feature_write = feature_valid && feature_ready && feature_address < DEPTH && feature_channel == c;
            wire a_write = feature_write || (write_enable && o == c && layer == 1);
            wire [12:0] a_address = feature_write?feature_address:write_address;
            wire signed [DATA_BITS - 1:0] a_data = feature_write?($signed(feature_data) >>> (16 -
                DATA_FRAC)):write_value;
            cnn_activation_ram #(.WIDTH(DATA_BITS), .DEPTH(DEPTH)) ram_a(
            .clk(clk), .we(a_write), .waddr(a_address), .wdata(a_data),
                .re(state == ISSUE), .raddr(source_address[12:0]), .rdata(activation_a));
            cnn_activation_ram #(.WIDTH(DATA_BITS), .DEPTH(DEPTH)) ram_b(
            .clk(clk), .we(write_enable && o == c && (layer == 0 || layer == 2)), .waddr(write_address),
                .wdata(write_value),
                .re(state == ISSUE), .raddr(source_address[12:0]), .rdata(activation_b));

            always @(posedge clk)
            begin
                if (state == ISSUE)
                begin
                    padding_valid <= source_valid;
                    weight <= rom[weight_address];
                end
            end
        end
    endgenerate

    always @(posedge clk)
    begin
        if (!rst_n)
        begin
            rd_valid <= 0;
            prod_valid <= 0;
            quarter_valid <= 0;
            half_valid <= 0;
            sum_valid <= 0;
            rd_last <= 0;
            prod_last <= 0;
            quarter_last <= 0;
            half_last <= 0;
            sum_last <= 0;
        end

        else
        begin
            rd_valid <= (state == ISSUE);
            rd_last <= (state == ISSUE && issued == kernel * kernel - 1);
            prod_valid <= rd_valid;
            prod_last <= rd_last;
            quarter_valid <= prod_valid;
            quarter_last <= prod_last;
            half_valid <= quarter_valid;
            half_last <= quarter_last;
            sum_valid <= half_valid;
            sum_last <= half_last;
        end
    end
    // The data pipeline is consumed only after its corresponding valid bit.
    // Keeping data registers free of reset lets the device pack them without
    // an extra reset control set; no invalid data reaches the accumulator.

    always @(posedge clk)
    begin
        if (rd_valid) for (integer i = 0;i < 16;i = i + 1) products[i] <=
            $signed(activations[i]) * $signed(weights[i]);
        if (prod_valid) for (integer i = 0;i < 4;i = i + 1) sum_quarter[i] <= sum_l2[i];
        if (quarter_valid)
        begin
            sum_half[0] <= half_add_0;
            sum_half[1] <= half_add_1;
        end
        if (half_valid) sum_reg <= final_sum_add;
    end

    always @(posedge clk)
    begin
        if (!rst_n)
        begin
            state <= IDLE;
            layer <= 0;
            run_frequency_count <= FREQ;
            f <= 0;
            t <= 0;
            o <= 0;
            kx <= 0;
            ky <= 0;
            issued <= 0;
            loaded <= 0;
            load_error <= 0;
            done <= 0;
            mask_valid <= 0;
            mask_address <= 0;
            mask_data <= 0;
            accumulator <= 0;
            finished_acc <= 0;
        end

        else
        begin
            done <= 0;
            if (feature_valid && feature_ready)
            begin
                if (feature_address < DEPTH && loaded < DEPTH * 8) loaded <= loaded + 1;
                else load_error <= 1;
            end
            if (sum_valid && (state == ISSUE || state == DRAIN)) accumulator <= final_acc;
            case
                (state)
                IDLE: if (start)
                begin
                    if (loaded != feature_frequency_count * TIME * 8 || feature_valid || feature_frequency_count == 0 ||
                        feature_frequency_count > FREQ) load_error <= 1;
                    else
                    begin
                        state <= INIT;
                        layer <= 0;
                        run_frequency_count <= feature_frequency_count;
                        f <= 0;
                        t <= 0;
                        o <= 0;
                        loaded <= 0;
                        load_error <= 0;
                    end
                end
                INIT:
                begin
                    accumulator <= ($signed(biases[bias_base + o]) >>> (16 - DATA_FRAC)) * 64'sd16384;
                    kx <= 0;
                    ky <= 0;
                    issued <= 0;
                    state <= ISSUE;
                end
                ISSUE:
                begin
                    issued <= issued + 1;
                    if (ky == kernel - 1)
                    begin
                        ky <= 0;
                        kx <= kx + 1;
                    end

                    else ky <= ky + 1;
                    if (issued == kernel * kernel - 1) state <= DRAIN;
                end
                DRAIN: if (sum_valid && sum_last)
                begin
                    finished_acc <= final_acc;
                    state <= WRITE;
                end
                WRITE:
                begin
                    if (layer == 3) mask_ram[write_address] <= write_mask;
                    state <= INIT;
                    if (o == cout - 1)
                    begin
                        o <= 0;
                        if (t == TIME - 1)
                        begin
                            t <= 0;
                            if (f == run_frequency_count - 1)
                            begin
                                f <= 0;
                                if (layer == 3)
                                begin
                                    state <= OUT_READ;
                                    mask_address <= 0;
                                end

                                else layer <= layer + 1;
                            end

                            else f <= f + 1;
                        end

                        else t <= t + 1;
                    end

                    else o <= o + 1;
                end
                OUT_READ:
                begin
                    mask_data <= mask_ram[mask_address];
                    mask_valid <= 1;
                    state <= OUT_HOLD;
                end
                OUT_HOLD: if (mask_ready)
                begin
                    mask_valid <= 0;
                    if (mask_address == run_frequency_count * TIME - 1)
                    begin
                        done <= 1;
                        state <= IDLE;
                    end

                    else
                    begin
                        mask_address <= mask_address + 1;
                        state <= OUT_READ;
                    end
                end
                default: state <= IDLE;
            endcase
        end
    end
endmodule

// Explicit 2048-word segments avoid rounding each 5140-word bank to 8192.

module cnn_activation_ram #(
    parameter WIDTH = 16,
    DEPTH = 5140,
    ADDR_BITS = 13
)
(
    input  wire clk,
    input  wire we,
    input  wire re,
    input  wire [ADDR_BITS - 1:0] waddr,
    input  wire [ADDR_BITS - 1:0] raddr,
    input  wire signed [WIDTH - 1:0] wdata,
    output wire signed [WIDTH - 1:0] rdata
);

    localparam SEGMENTS = (DEPTH + 2047) / 2048;
    reg [ADDR_BITS - 12:0] selected;
    wire signed [WIDTH - 1:0] outputs[0:SEGMENTS - 1];

    always @(posedge clk) if (re) selected <= raddr[ADDR_BITS - 1:11];
    assign rdata = (selected < SEGMENTS)?outputs[selected]:0;
    genvar s;
    generate
        for (s = 0;s < SEGMENTS;s = s + 1)
        begin
            :segment
            localparam SEG_DEPTH = ((s + 1) * 2048 > DEPTH)?(DEPTH - s * 2048):2048;
            (* ram_style="block" *) reg signed [WIDTH - 1:0] memory[0:SEG_DEPTH - 1];
            reg signed [WIDTH - 1:0] value;
            assign outputs[s] = value;

            always @(posedge clk)
            begin
                if (we && waddr[ADDR_BITS - 1:11] == s) memory[waddr[10:0]] <= wdata;
                if (re) value <= memory[raddr[10:0]];
            end
        end
    endgenerate
endmodule
